from __future__ import annotations


def _amount_is_positive(record: dict) -> bool:
    """Evaluate: NVL(AMT,0) > 0."""
    value = record.get("AMT", "")
    if value is None or value == "":
        value = 0

    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def _has_close_date(record: dict) -> bool:
    """Evaluate: CLOSE_DT <> '00000000'."""
    return record.get("CLOSE_DT", "") != "00000000"


def _has_lost_reason(record: dict) -> bool:
    """Evaluate: LOST_RSN <> ''."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity_pipeline workflow event without mutating *record*."""
    result_record = record.copy()

    # XML document order is preserved below.
    if state == "P" and event == "qualify" and _amount_is_positive(record):
        result_record["STAGE_PCT"] = "25"
        return {
            "state": "Q",
            "record": result_record,
            "audits": ["OPP_QUAL"],
            "notifies": [],
            "matched": True,
        }

    if state == "Q" and event == "advance":
        result_record["STAGE_PCT"] = "60"
        return {
            "state": "N",
            "record": result_record,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_won" and _has_close_date(record):
        result_record["STAGE_PCT"] = "100"
        return {
            "state": "W",
            "record": result_record,
            "audits": ["OPP_WON"],
            "notifies": ["won_deal"],
            "matched": True,
        }

    if state == "P" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "Q" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "close_lost" and _has_lost_reason(record):
        result_record["STAGE_PCT"] = "0"
        return {
            "state": "L",
            "record": result_record,
            "audits": ["OPP_LOST"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
